public class ArrayOperations {
    public static void main(String[] args) {
        // Initialize array
        int[] numbers = {5, 2, 8, 1, 9, 3};

        // Find maximum value
        int max = numbers[0];
        for (int num : numbers) {
            if (num > max) {
                max = num;
            }
        }

        // Calculate average
        double sum = 0;
        for (int num : numbers) {
            sum += num;
        }
        double average = sum / numbers.length;

        // Print results
        System.out.println("Maximum value: " + max);
        System.out.println("Average value: " + average);
    }
}

