import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class CustomThreadPool {
    private final WorkStealingQueue<Runnable>[] queues;
    private final Thread[] threads;
    private final AtomicInteger index;
    private volatile boolean isShutdown;

    @SuppressWarnings("unchecked")
    public CustomThreadPool(int nThreads) {
        this.queues = new WorkStealingQueue[nThreads];
        this.threads = new Thread[nThreads];
        this.index = new AtomicInteger();

        for (int i = 0; i < nThreads; i++) {
            queues[i] = new WorkStealingQueue<>();
            threads[i] = new WorkerThread(i);
            threads[i].start();
        }
    }

    public void submit(Runnable task) {
        if (isShutdown) {
            throw new RejectedExecutionException("ThreadPool is shutdown");
        }
        int idx = index.getAndIncrement() % queues.length;
        queues[idx].offer(task);
    }

    public void shutdown() {
        isShutdown = true;
        for (Thread thread : threads) {
            thread.interrupt();
        }
    }

    private class WorkerThread extends Thread {
        private final int index;

        WorkerThread(int index) {
            this.index = index;
        }

        @Override
        public void run() {
            while (!isShutdown || !queues[index].isEmpty()) {
                Runnable task = queues[index].poll();
                if (task != null) {
                    task.run();
                } else {
                    // Try to steal work from other queues
                    task = stealTask();
                    if (task != null) {
                        task.run();
                    } else {
                        Thread.yield();
                    }
                }
            }
        }

        private Runnable stealTask() {
            for (int i = 0; i < queues.length; i++) {
                if (i != index) {
                    Runnable task = queues[i].steal();
                    if (task != null) {
                        return task;
                    }
                }
            }
            return null;
        }
    }
}

import javax.annotation.processing.*;
import javax.lang.model.element.*;
import javax.tools.JavaFileObject;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Set;

@SupportedAnnotationTypes("com.example.Generator")
public class CustomProcessor extends AbstractProcessor {
    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (TypeElement annotation : annotations) {
            Set<? extends Element> elements = roundEnv.getElementsAnnotatedWith(annotation);

            for (Element element : elements) {
                if (element.getKind() != ElementKind.CLASS) {
                    continue;
                }

                String className = element.getSimpleName().toString();
                String packageName = processingEnv.getElementUtils()
                    .getPackageOf(element)
                    .getQualifiedName()
                    .toString();

                try {
                    generateWrapper(packageName, className);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
        return true;
    }

    private void generateWrapper(String packageName, String className) throws IOException {
        String wrapperName = className + "Wrapper";
        String qualifiedName = packageName + "." + wrapperName;

        JavaFileObject builderFile = processingEnv.getFiler()
            .createSourceFile(qualifiedName);

        try (PrintWriter out = new PrintWriter(builderFile.openWriter())) {
            out.println("package " + packageName + ";");
            out.println();
            out.println("public class " + wrapperName + " {");
            out.println("    private final " + className + " instance;");
            out.println();
            out.println("    public " + wrapperName + "(" + className + " instance) {");
            out.println("        this.instance = instance;");
            out.println("    }");
            out.println();
            out.println("    // Generated wrapper methods will go here");
            out.println("}");
        }
    }
}
